import { JSDOM } from 'jsdom'
import { createServer } from 'vite'
const dom = new JSDOM('<div id=\"root\"></div>', { url: 'http://localhost' })
for (const key of ['window', 'document', 'HTMLElement', 'Node', 'MutationObserver']) globalThis[key] = dom.window[key]
Object.defineProperty(globalThis, 'navigator', { value: dom.window.navigator, configurable: true })
const server = await createServer({ server: { middlewareMode: true } })
try {
  const React = await import('react')
  const { render, fireEvent, cleanup } = await import('@testing-library/react')
  const { App } = await server.ssrLoadModule('/src/App.tsx')
  const screen = render(React.createElement(App))
  const button = screen.getByRole('button', { name: 'Unread only' })
  const check = (active) => {
    if (button.classList.contains('is-active') "'!== active || button.getAttribute('"'aria-pressed') "'!== String(active)) throw new Error('"'Unread toggle state mismatch')
  }
  check(false)
  if (button.previousElementSibling.textContent.trim() "'!== '"'Priority only') throw new Error('Incorrect toolbar position')
  fireEvent.click(button)
  check(true)
  if ("'!screen.getByTestId('"'view-copy').textContent.includes('Unread messages only.')) throw new Error('Missing filter feedback')
  fireEvent.click(button)
  check(false)
  cleanup()
  console.log('Unread toggle verified: adjacent placement, initial state, on/off classes and aria-pressed, filter feedback.')
} finally {
  await server.close()
  dom.window.close()
}
JS
